package main

import (
	"errors"
	"fmt"
)

type User struct {
	id       int
	username string
	email    string
	active   bool
}

var nextID = 1

func NewUser(username, email string) (*User, error) {
	if username == "" {
		return nil, errors.New("username cannot be empty")
	}
	if len(username) < 3 {
		return nil, fmt.Errorf("username too short: minimum 3 chars, got %d", len(username))
	}
	if email == "" {
		return nil, errors.New("email cannot be empty")
	}
	u := &User{
		id:       nextID,
		username: username,
		email:    email,
		active:   true,
	}
	nextID++
	return u, nil
}

func (u *User) ID() int         { return u.id }
func (u *User) Username() string { return u.username }
func (u *User) Email() string   { return u.email }
func (u *User) IsActive() bool  { return u.active }
func (u *User) Deactivate()     { u.active = false }

func (u User) String() string {
	status := "active"
	if !u.active {
		status = "inactive"
	}
	return fmt.Sprintf("User{id:%d, username:%s, status:%s}", u.id, u.username, status)
}

// Zero-value friendly stack
type Stack struct {
	items []int
}

func (s *Stack) Push(v int)        { s.items = append(s.items, v) }
func (s *Stack) Len() int          { return len(s.items) }
func (s *Stack) Pop() (int, bool) {
	if len(s.items) == 0 {
		return 0, false
	}
	n := len(s.items) - 1
	v := s.items[n]
	s.items = s.items[:n]
	return v, true
}

func main() {
	// Valid user
	u1, err := NewUser("alice", "alice@example.com")
	if err != nil {
		fmt.Println("Error:", err)
	} else {
		fmt.Println(u1)
	}

	// Invalid user
	_, err = NewUser("", "bob@example.com")
	if err != nil {
		fmt.Println("Error:", err)
	}

	_, err = NewUser("ab", "ab@example.com")
	if err != nil {
		fmt.Println("Error:", err)
	}

	// Zero-value friendly stack
	var s Stack
	s.Push(10)
	s.Push(20)
	s.Push(30)
	fmt.Printf("Stack len: %d\n", s.Len())
	for s.Len() > 0 {
		v, _ := s.Pop()
		fmt.Printf("Pop: %d\n", v)
	}
}
